import sys
from collections import defaultdict

def read_matrix():
    n = int(sys.stdin.readline().strip())
    elements = []
    for _ in range(n):
        parts = sys.stdin.readline().strip().split()
        if len(parts) >= 3:
            row, col, val = int(parts[0]), int(parts[1]), int(parts[2])
            elements.append((row, col, val))
    return elements

def add_matrices(a, b):
    result_map = defaultdict(int)
    for row, col, val in a:
        result_map[(row, col)] += val
    for row, col, val in b:
        result_map[(row, col)] += val
    result = []
    for (row, col), val in result_map.items():
        if val != 0:
            result.append((row, col, val))
    result.sort(key=lambda x: (x[0], x[1]))
    return result

def subtract_matrices(a, b):
    result_map = defaultdict(int)
    for row, col, val in a:
        result_map[(row, col)] += val
    for row, col, val in b:
        result_map[(row, col)] -= val
    result = []
    for (row, col), val in result_map.items():
        if val != 0:
            result.append((row, col, val))
    result.sort(key=lambda x: (x[0], x[1]))
    return result

def print_matrix(elements, operation):
    print(f"{operation} Result:")
    for row, col, val in elements:
        print(f"{row} {col} {val}")

def main():
    a = read_matrix()
    b = read_matrix()

    sum_result = add_matrices(a, b)
    diff_result = subtract_matrices(a, b)

    print_matrix(sum_result, "Addition")
    print()
    print_matrix(diff_result, "Subtraction")

if __name__ == "__main__":
    main()
